pub fn paths(n: Int, edges: List[List[Int]], src: Int) -> List[Int] {
  var dist: List[Int] = []
  var seen: List[Bool] = []
  for _i in range(0, n) {
    dist = dist.push(-1)
    seen = seen.push(false)
  }
  dist = dist.set(src, 0)
  var step = 0
  while step < n {
    var best = -1
    for v in range(0, n) {
      let dv = dist.get_or(v, -1)
      if (not seen.get_or(v, true)) and dv >= 0 {
        if best < 0 or dv < dist.get_or(best, -1) {
          best = v
        }
      }
    }
    if best >= 0 {
      seen = seen.set(best, true)
      let db = dist.get_or(best, 0)
      for e in edges {
        if e.get_or(0, -1) == best {
          let dst = e.get_or(1, 0)
          let nd = db + e.get_or(2, 0)
          let cur = dist.get_or(dst, -1)
          if cur < 0 or nd < cur {
            dist = dist.set(dst, nd)
          }
        }
      }
    }
    step = step + 1
  }
  return dist
}
